package dev.veltraph.client.rotation;
import org.junit.jupiter.api.Test;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
class SourceRotationBusyTest {
    final SourceRotationStepper.Settings settings=SourceRotationStepper.Settings.standard(.5,1);
    @Test void pendingWithoutAnActualControllerCalculationIsNotBusy(){var request=new RotationRequest(new SourceRotationStepper());request.replace(90,0,null);assertTrue(request.pending());assertFalse(request.sourceBusy(0,0));}
    @Test void actualQuantizedYawSpeedAboveProcessThresholdIsBusy(){var request=new RotationRequest(new SourceRotationStepper());request.replace(90,0,null);var step=request.advance(0,0,settings,true,false);assertEquals(24.45,step.yawSpeed(),1e-4);assertTrue(request.sourceBusy(0,0));assertTrue(request.pending());}
    @Test void slowPendingControllerDoesNotBecomeBusyFromTargetDistance(){var request=new RotationRequest(new SourceRotationStepper());request.replace(90,0,null);var step=request.advance(0,0,SourceRotationStepper.Settings.standard(.5,.1),true,false);assertTrue(step.yawSpeed()<5);assertTrue(request.pending());assertFalse(request.sourceBusy(0,0));}
    @Test void actualPitchSpeedCanBeBusyWhenYawSpeedIsBelowThreshold(){var request=new RotationRequest(new SourceRotationStepper());request.replace(0,90,null);var step=request.advance(0,0,settings,true,false);assertTrue(step.yawSpeed()<5);assertTrue(step.pitchSpeed()>7);assertTrue(request.sourceBusy(0,0));}
    @Test void euclideanNearEndpointAndStrictThresholdFollowSourceBoundaries(){assertFalse(SourceRotationBusy.evaluate(true,true,90,0,90,-.099f,true,20,20,6));assertTrue(SourceRotationBusy.evaluate(true,true,90,0,90,-.1f,true,20,20,6));assertFalse(SourceRotationBusy.evaluate(true,true,90,0,0,0,true,6,6,6));assertTrue(SourceRotationBusy.evaluate(true,true,90,0,0,0,true,6.001f,1,6));assertFalse(SourceRotationBusy.evaluate(true,true,-179,0,181,0,true,20,20,6));}
    @Test void retainedTargetActivityIsIndependentOfRotatingFlagAndNeedsYawController(){assertTrue(SourceRotationBusy.evaluate(false,true,90,0,0,0,true,8,1,6));assertThrows(IllegalStateException.class,()->SourceRotationBusy.evaluate(true,false,90,0,0,0,true,8,1,6));assertFalse(SourceRotationBusy.evaluate(true,true,90,0,0,0,false,8,1,6));}
    @Test void queriesNeverAdvanceCurvesCompleteCallbacksOrChangeFutureSteps(){var a=new RotationRequest(new SourceRotationStepper());var b=new RotationRequest(new SourceRotationStepper());var callback=new AtomicInteger();a.replace(90,20,callback::incrementAndGet);b.replace(90,20,null);var initial=a.advance(0,0,settings,true,false);assertEquals(initial,b.advance(0,0,settings,true,false));for(int i=0;i<100;i++)a.sourceBusy(initial.yaw(),initial.pitch());var changed=new SourceRotationStepper.Settings(.5,1,1,1,2,.8);assertEquals(b.advance(initial.yaw(),initial.pitch(),changed,true,false),a.advance(initial.yaw(),initial.pitch(),changed,true,false));assertEquals(0,callback.get());assertTrue(a.pending());}
    @Test void explicitCancellationClearsTargetAndPriorControllerEvidence(){var request=new RotationRequest(new SourceRotationStepper());request.replace(90,0,null);request.advance(0,0,settings,true,false);assertTrue(request.sourceBusy(0,0));request.cancel();assertFalse(request.sourceBusy(0,0));assertFalse(request.pending());}
    @Test void actualCompletionResetsTargetAndReentrantCallbackKeepsItsNewRequest(){var request=new RotationRequest(new SourceRotationStepper());var callback=new AtomicInteger();request.replace(0,0,()->{assertFalse(request.sourceBusy(90,0));callback.incrementAndGet();request.replace(90,0,null);});var step=request.advance(0,0,settings,true,false);request.applied(step);assertEquals(1,callback.get());assertTrue(request.pending());assertFalse(request.sourceBusy(0,0));request.advance(0,0,settings,true,false);assertTrue(request.sourceBusy(0,0));}
    @Test void processThresholdIsSampledOnceInExactRecoveredRange(){double first=SourceRotationBusy.threshold();assertTrue(first>=5&&first<7);for(int i=0;i<100;i++)assertEquals(first,SourceRotationBusy.threshold());assertThrows(IllegalArgumentException.class,()->SourceRotationBusy.evaluate(true,true,90,0,0,0,true,20,20,7));}
    @Test void nonSourceAdapterDefaultsIdleAndQueryDoesNotAim(){var adapter=new dev.veltraph.client.testutil.FakeRotationService();assertFalse(adapter.sourceBusy());assertEquals(0,adapter.aimCalls);}
}
